syntax:
pid_t fork(void);
int execl(const char *path, const char *arg0, ... , NULL);
int execlp(const char *file, const char *arg0, ... , NULL); // other exec variants exist

code_example:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
int main() {
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork failed");
        exit(1);
    }
    else if (pid == 0) {
        // Child process
        execlp("date", "date", NULL);
        perror("execlp failed"); // only reached if execlp fails
        exit(1);
    } else {
        // Parent process
        wait(NULL); // Wait for child to finish
        printf("Child process completed\n");
    }
    return 0;
}
